    pub(crate) fn compare_ecuc_module_def(
        &self,
        other: &Document,
        a: &EcucModuleDef,
        b: &EcucModuleDef,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ecuc_definition_element(other, a.base(), b.base(), path)?;
        if a.get_api_service_prefix() != b.get_api_service_prefix() {
            return Err(format!("{path}: API_SERVICE_PREFIX mismatch"));
        }
        let list_a = a.get_containers();
        let list_b = b.get_containers();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CONTAINERS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.CONTAINERS[{index}] mismatch"));
            }
        }
        if a.get_post_build_variant_support() != b.get_post_build_variant_support() {
            return Err(format!("{path}: POST_BUILD_VARIANT_SUPPORT mismatch"));
        }
        if a.get_refined_module_def_ref() != b.get_refined_module_def_ref() {
            return Err(format!("{path}: REFINED_MODULE_DEF_REF mismatch"));
        }
        let list_a = a.get_supported_config_variants();
        let list_b = b.get_supported_config_variants();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SUPPORTED_CONFIG_VARIANTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.SUPPORTED_CONFIG_VARIANTS[{index}] mismatch"
                ));
            }
        }
        Ok(())
    }

