    pub(crate) fn compare_ecuc_validation_condition(
        &self,
        other: &Document,
        a: &EcucValidationCondition,
        b: &EcucValidationCondition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_ecuc_queries();
        let list_b = b.get_ecuc_queries();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ECUC_QUERIES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ecuc_querys.get(*x).ok_or_else(|| {
                format!("{path}.ECUC_QUERIES[{index}]: id not found in own arena")
            })?;
            let y = other.ecuc_querys.get(*y).ok_or_else(|| {
                format!("{path}.ECUC_QUERIES[{index}]: id not found in other arena")
            })?;
            self.compare_ecuc_query(other, x, y, &format!("{path}.ECUC_QUERIES[{index}]"))?;
        }
        if a.get_validation_formula() != b.get_validation_formula() {
            return Err(format!("{path}: VALIDATION_FORMULA mismatch"));
        }
        Ok(())
    }

